parameters.jsCode:
// Compare the roles on the careers page with the open roles of this company, read from Airtable at the start.
const settings = $('Settings').first().json;
const company = $('Loop over companies').first().json;
const roles = $('Read the careers page').first().json.actions?.[0]?.output?.roles || [];
const openJobs = $('Read the open roles').all().map((item) => item.json)
  .filter((job) => job.id && (job.fields.Company || []).includes(company.id));
const today = $today.toISODate();

// Role links can be relative. Roles are matched on title and team, the model can miscopy the long ids in links.
const origin = (company.fields['Careers page'].match(/^https?:\/\/[^/]+/) || [''])[0];
const absolute = (link) => (link && link.startsWith('/') ? origin + link : link || '');

// Match one to one, so the same title in two cities counts as two roles. Within a title, prefer the same location.
const norm = (text) => (text || '').trim().toLowerCase().replace(/\s+/g, ' ');
const keyOf = (title, team) => norm(`${title || ''} | ${team || ''}`);
const open = new Map();
for (const job of openJobs) {
  const key = keyOf(job.fields.Title, job.fields.Team);
  open.set(key, [...(open.get(key) || []), job]);
}
const takeMatch = (role) => {
  const bucket = open.get(keyOf(role.title, role.team)) || [];
  if (!bucket.length) return null;
  const same = bucket.findIndex((job) => norm(job.fields.Location) === norm(role.location));
  return bucket.splice(same >= 0 ? same : 0, 1)[0];
};
const pageRoles = roles.map((role) => ({ ...role, link: absolute(role.link) }));
const newRoles = pageRoles.filter((role) => !takeMatch(role));
const goneJobs = [...open.values()].flat();

// Close roles only when the page still lists most of the open ones, otherwise the read was probably partial.
const stillListed = openJobs.length - goneJobs.length;
const safeToClose = stillListed >= settings.min_share * openJobs.length;

return [{
  json: {
    new_roles: newRoles.map((role) => ({
      Title: role.title,
      ...(role.link ? { Link: role.link } : {}),
      Team: role.team,
      Location: role.location,
      'First seen': today,
      Company: [company.id],
    })),
    closed_roles: safeToClose ? goneJobs.map((job) => ({ id: job.id, 'Closed on': today })) : [],
    open_roles: pageRoles.length,
    new_count: newRoles.length,
    status: safeToClose
      ? 'ok'
      : `check the page: ${pageRoles.length} roles found, only ${stillListed} of ${openJobs.length} open roles still listed, nothing closed`,
  },
}];
